<?php
namespace ProjectPress\Includes\Project\People;use ProjectPress\Includes\Functions\Helpers\DBHelper;if(!defined('ABSPATH')){exit;}final class TimeSheetRepository{public function find(int$id):?TimeSheet{$row=DBHelper::get_by_id('timesheets',absint($id));return is_array($row)?new TimeSheet($row):null;}public function for_project(int$id):array{return array_map(static fn(array$row):TimeSheet=>new TimeSheet($row),DBHelper::get_all('timesheets',array('project_id'=>absint($id)),'*','work_date DESC,created_at DESC'));}public function create(int$id,array$data){$now=current_time('mysql',true);$record=DBHelper::insert('timesheets',array_merge($data,array('project_id'=>absint($id),'created_by'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now)));return false===$record?false:$this->find((int)$record);}public function delete(TimeSheet$record):bool{return DBHelper::delete('timesheets',array('id'=>$record->get_id(),'project_id'=>$record->get_project_id()));}}
